import{_ as a,c as t,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/lif-series.webp",p=JSON.parse('{"title":"Leica LIF Viewer","description":"Free online Leica LIF viewer: open .lif projects from LAS X in your browser, every image, Z-stack, time series and tile scan, and single .lof images. From your disk or a link. Nothing to install.","frontmatter":{"title":"Leica LIF Viewer","description":"Free online Leica LIF viewer: open .lif projects from LAS X in your browser, every image, Z-stack, time series and tile scan, and single .lof images. From your disk or a link. Nothing to install."},"headers":[],"relativePath":"guides/leica-lif.md","filePath":"guides/leica-lif.md"}'),n={name:"guides/leica-lif.md"};function s(l,e,d,h,c,f){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="leica-lif-viewer" tabindex="-1">Leica LIF Viewer <a class="header-anchor" href="#leica-lif-viewer" aria-label="Permalink to &quot;Leica LIF Viewer&quot;">​</a></h1><p>Open a <code>.lif</code> project from Leica LAS X with every image in it. Confocal Z-stacks, time series, tile scans and lambda scans from SP5, SP8 and Stellaris systems open as they are. No Fiji, no Bio-Formats export, no upload. A single image saved as <code>.lof</code> opens too.</p><p><img src="'+i+'" alt="Project007.lif open in the viewer: a stitched tile scan of a neuron, with the project&#39;s images in the Series list"></p><h2 id="how-to-open-a-lif-file" tabindex="-1">How to Open a LIF File <a class="header-anchor" href="#how-to-open-a-lif-file" aria-label="Permalink to &quot;How to Open a LIF File&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of LIF files</strong>, in Chrome and Edge. One file opens, several show a list, including files one folder down. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>, or a Zenodo file link that ends in <code>/content</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><p>The viewer reads only the parts it shows. A 3 GB project opens in a few requests, and pictures arrive as you look at them.</p><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Every image of the project.</strong> The <strong>Series</strong> list names each one by its place in the project, such as <code>FRET_AB_423_001/Bleach003</code>. Folders are not listed.</li><li><strong>Channels.</strong> Colours come from the LUT each channel was recorded with in LAS X.</li><li><strong>Lambda scans.</strong> Each wavelength is a channel, named by its wavelength, such as <code>420 nm</code>, and drawn in the colour of its wavelength, from violet to red. Turn channels on and off to compare them.</li><li><strong>Z and time.</strong> Sliders step through the planes, in the order they were recorded. A Z-stack can also be viewed in 3D. See <a href="./3d-rendering.html">3D Rendering</a>.</li><li><strong>Tile scans, stitched.</strong> The tiles are placed where the stage recorded them, and a later tile covers an earlier one where they overlap. When LAS X also saved its own stitched copy, the <strong>Merged</strong> image, it is listed next to the tile scan. LAS X aligns tiles when it merges, so where you need seamless edges, open the Merged image.</li><li><strong>8, 12 and 16-bit data.</strong> 12-bit images open with their full range.</li><li><strong>Pixel size and Z step</strong> from the file. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>LAS X stores each image at one resolution. The viewer makes the lower resolutions itself, so zooming out stays smooth.</p><h2 id="if-an-image-is-not-shown" tabindex="-1">If an Image Is Not Shown <a class="header-anchor" href="#if-an-image-is-not-shown" aria-label="Permalink to &quot;If an Image Is Not Shown&quot;">​</a></h2><p>A project can hold images the viewer cannot show yet. The others open, and a note names what was left out:</p><table tabindex="0"><thead><tr><th>What the image has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>One plane of all channels over 256 MB</td><td>too large to open without a pyramid. Convert it to OME-Zarr to open it here.</td></tr><tr><td>A lambda scan of several channels</td><td>a lambda scan of several channels, which the viewer does not open yet.</td></tr><tr><td>An excitation lambda scan, or another axis</td><td>has a spectral (λ) axis, which the viewer does not show yet.</td></tr><tr><td>A tile scan stored mirrored or turned</td><td>a tile scan stored mirrored or turned. Open its Merged image instead, if the project has one.</td></tr><tr><td>Float or 32-bit samples</td><td>32-bit data, which the viewer does not read yet.</td></tr></tbody></table><p>When no image of a project can be shown, the file does not open, and the note lists every reason. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">Convert it to OME-Zarr</a> to open a very large image with every resolution.</p><h2 id="lof-files" tabindex="-1">LOF Files <a class="header-anchor" href="#lof-files" aria-label="Permalink to &quot;LOF Files&quot;">​</a></h2><p>LAS X can save one image on its own as a <code>.lof</code> file (Leica Object File). It opens like a project with one image: drop it on the viewer, choose it under <strong>Open Image</strong>, or paste its address. The image keeps the name it has in LAS X. What the viewer cannot show yet is the same as for a LIF, in the table above.</p><p>A folder of <code>.lof</code> files with an <code>.xlef</code> file is a whole LAS X project exported as files. Open its <code>.lof</code> files one at a time for now.</p><h2 id="public-lif-files-to-try" tabindex="-1">Public LIF Files to Try <a class="header-anchor" href="#public-lif-files-to-try" aria-label="Permalink to &quot;Public LIF Files to Try&quot;">​</a></h2><ul><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F6606445%2Ffiles%2FProject007.lif%2Fcontent" target="_blank" rel="noreferrer">Project007.lif</a>: confocal Z-stacks of a neuron and a 2 x 2 tile scan with its Merged image. Peter Zentis, <a href="https://zenodo.org/records/6606445" target="_blank" rel="noreferrer">Zenodo 6606445</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F15353569%2Ffiles%2FAMR1.lif%2Fcontent" target="_blank" rel="noreferrer">AMR1.lif</a>: 3 GB, 12-bit, five channels, three tile scans with their Merged and processed copies. Pamela Young, <a href="https://zenodo.org/records/15353569" target="_blank" rel="noreferrer">Zenodo 15353569</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F14976703%2Ffiles%2FConvalaria_LambdaScan.lif%2Fcontent" target="_blank" rel="noreferrer">Convalaria_LambdaScan.lif</a>: a lambda scan of Convallaria from a STELLARIS 8, 29 wavelengths from 420 to 700 nm. Maria Manuela Azevedo, <a href="https://zenodo.org/records/14976703" target="_blank" rel="noreferrer">Zenodo 14976703</a>, CC BY 4.0.</li></ul><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a file by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Project007.lif</code>, (c) Peter Zentis, <a href="https://zenodo.org/records/6606445" target="_blank" rel="noreferrer">Zenodo 6606445</a>, CC BY 4.0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;Leica LIF file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',24)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
